"""
Verifiers environment module implementing a fixed scoring contract.

Criteria (in order), weights:
  cited_confidence      0.25
  exact_match          -0.30
  used_tool             0.20
  contains_answer       0.15
  starts_capitalized    0.10
  word_count            0.00   (diagnostic only)

Rules:
  - AGGREGATION: raw weighted sum, no normalization/rescaling.
  - ERROR RULE: missing/malformed info key -> 0.0 for that criterion, never raise.
  - EXCLUSION RULE: if info["excluded"] is True, all WEIGHTED criteria -> 0.0;
    zero-weight diagnostics still compute their real value.
"""

import verifiers as vf
from datasets import Dataset


def _is_excluded(info) -> bool:
    try:
        return info.get("excluded") is True
    except AttributeError:
        return False


def cited_confidence(completion, answer, info, **kwargs) -> float:
    if _is_excluded(info):
        return 0.0
    try:
        val = float(info["confidence"])
    except (KeyError, TypeError, ValueError):
        return 0.0
    if val < 0.0:
        return 0.0
    if val > 1.0:
        return 1.0
    return val


def exact_match(completion, answer, info, **kwargs) -> float:
    if _is_excluded(info):
        return 0.0
    try:
        return 1.0 if completion == answer else 0.0
    except Exception:
        return 0.0


def used_tool(completion, answer, info, **kwargs) -> float:
    if _is_excluded(info):
        return 0.0
    try:
        return 1.0 if bool(info["tool_used"]) else 0.0
    except (KeyError, TypeError):
        return 0.0


def contains_answer(completion, answer, info, **kwargs) -> float:
    if _is_excluded(info):
        return 0.0
    try:
        return 1.0 if answer in completion else 0.0
    except TypeError:
        return 0.0


def starts_capitalized(completion, answer, info, **kwargs) -> float:
    if _is_excluded(info):
        return 0.0
    try:
        if not completion:
            return 0.0
        return 1.0 if completion[:1].isupper() else 0.0
    except (TypeError, AttributeError):
        return 0.0


def word_count(completion, answer, info, **kwargs) -> float:
    try:
        return float(len(completion.split()))
    except (TypeError, AttributeError):
        return 0.0


def load_environment(**kwargs):
    dataset = Dataset.from_list([{"question": "stub", "answer": "stub"}])

    funcs = [
        cited_confidence,
        exact_match,
        used_tool,
        contains_answer,
        starts_capitalized,
        word_count,
    ]
    weights = [0.25, -0.3, 0.2, 0.15, 0.1, 0.0]

    rubric = vf.Rubric(funcs=funcs, weights=weights)

    return vf.SingleTurnEnv(dataset=dataset, rubric=rubric, **kwargs)
